"""Policy syntax, AST and declared per-policy bounds.

This module intentionally evaluates no predicates.  It parses exactly the
language from the protocol and checks all syntax-local limits.  Registry
membership is checked later at staging time; occurrence counts for a
syntactically/bounds-valid string are still available when it names an
unregistered service.
"""
from __future__ import annotations

WS = " \t\f\r\n"
# The grammar's only ignored whitespace.  Vertical tab and every other
# Unicode whitespace character are deliberately not here.
ATOM_KINDS = ("match", "startswith", "endswith", "contains")
NONMATCH_KINDS = ("startswith", "endswith", "contains")

class PolicyError(ValueError):
    pass

class Pred:
    __slots__ = ("kind", "path", "left", "right", "child", "atoms", "depth",
                 "ps", "nmi")
    def __init__(self, kind, path=(), left=None, right=None, child=None,
                 atoms=1, depth=1):
        self.kind = kind
        self.path = path          # tuple of service names for atoms
        self.left = left
        self.right = right
        self.child = child
        self.atoms = atoms
        self.depth = depth
        # Filled by create_dfa after registry symbol binding.
        self.ps = None
        self.nmi = -1

class ParsedPolicy:
    __slots__ = ("rules", "atoms", "path_symbols", "match_paths",
                 "nonmatch_atoms", "referenced_names")
    def __init__(self, rules, atoms, path_symbols, match_paths,
                 nonmatch_atoms, referenced_names):
        # rules is [(Pred, "allow"|"drop"), ...]
        self.rules = rules
        self.atoms = atoms
        self.path_symbols = path_symbols
        self.match_paths = match_paths              # set of name tuples
        self.nonmatch_atoms = nonmatch_atoms        # insertion-ordered list
        self.referenced_names = referenced_names

_EMPTY = object()

class _Lexer:
    __slots__ = ("text", "n", "pos", "cur")
    def __init__(self, text):
        self.text = text
        self.n = len(text)
        self.pos = 0
        self.cur = _EMPTY

    def _scan(self):
        text = self.text
        n = self.n
        i = self.pos
        while i < n and text[i] in WS:
            i += 1
        if i >= n:
            self.pos = i
            return None
        c = text[i]
        if c in "(),;":
            self.pos = i + 1
            return (c, c)
        if ("A" <= c <= "Z") or ("a" <= c <= "z"):
            start = i
            i += 1
            while i < n:
                d = text[i]
                if ("A" <= d <= "Z") or ("a" <= d <= "z") or ("0" <= d <= "9"):
                    i += 1
                else:
                    break
            if i - start > 24:
                raise PolicyError("identifier bound")
            self.pos = i
            return ("WORD", text[start:i])
        # This includes VT, NBSP, unpaired surrogate code points, and all
        # punctuation not in the tiny policy grammar.
        raise PolicyError("syntax")

    def peek(self):
        if self.cur is _EMPTY:
            self.cur = self._scan()
        return self.cur

    def pop(self):
        tok = self.peek()
        self.cur = _EMPTY
        return tok

    def expect(self, kind, value=None):
        tok = self.pop()
        if tok is None or tok[0] != kind or (value is not None and tok[1] != value):
            raise PolicyError("syntax")
        return tok

    def accept(self, kind, value=None):
        tok = self.peek()
        if tok is not None and tok[0] == kind and (value is None or tok[1] == value):
            self.pop()
            return tok
        return None

class _Parser:
    __slots__ = ("lex", "atoms", "path_symbols", "match_paths",
                 "nonmatch_set", "nonmatch_atoms", "referenced")
    def __init__(self, text):
        self.lex = _Lexer(text)
        self.atoms = 0
        self.path_symbols = 0
        self.match_paths = set()
        self.nonmatch_set = set()
        self.nonmatch_atoms = []
        self.referenced = set()

    def _path(self):
        # Opening '(' has already been consumed.
        tok = self.lex.peek()
        path = []
        if tok is not None and tok[0] == ")":
            self.lex.pop()
            return tuple(path)
        tok = self.lex.expect("WORD")
        path.append(tok[1])
        while True:
            tok = self.lex.peek()
            if tok is not None and tok[0] == ",":
                self.lex.pop()
                path.append(self.lex.expect("WORD")[1])
            else:
                break
        self.lex.expect(")")
        if len(path) > 16:
            raise PolicyError("path bound")
        return tuple(path)

    def _atom(self, kind, path):
        self.atoms += 1
        if self.atoms > 32768:
            raise PolicyError("atom total")
        self.path_symbols += len(path)
        if self.path_symbols > 65536:
            raise PolicyError("path total")
        self.referenced.update(path)
        if kind == "match":
            self.match_paths.add(path)
        else:
            if len(path) > 4:
                raise PolicyError("non-match path bound")
            key = (kind, path)
            if key not in self.nonmatch_set:
                if len(self.nonmatch_set) >= 4:
                    raise PolicyError("non-match atom bound")
                self.nonmatch_set.add(key)
                self.nonmatch_atoms.append(key)
        return Pred("atom", path=path)

    def _predicate(self, level):
        # The deepest atom of a depth-16 predicate is visited at level 16.
        # This guard also protects Python's call stack on malformed input.
        if level > 16:
            raise PolicyError("depth")
        tok = self.lex.peek()
        if tok is None:
            raise PolicyError("syntax")
        if tok[0] == "(":
            self.lex.pop()
            left = self._predicate(level + 1)
            optok = self.lex.peek()
            if optok is None or optok[0] != "WORD" or optok[1] not in ("and", "or"):
                raise PolicyError("syntax")
            op = self.lex.pop()[1]
            right = self._predicate(level + 1)
            self.lex.expect(")")
            depth = 1 + (left.depth if left.depth >= right.depth else right.depth)
            if depth > 16:
                raise PolicyError("depth")
            return Pred(op, left=left, right=right,
                        atoms=left.atoms + right.atoms, depth=depth)
        if tok[0] != "WORD":
            raise PolicyError("syntax")
        word = tok[1]
        if word in ATOM_KINDS:
            self.lex.pop()
            self.lex.expect("(")
            path = self._path()
            return self._atom(word, path)
        if word == "not":
            self.lex.pop()
            self.lex.expect("(")
            child = self._predicate(level + 1)
            self.lex.expect(")")
            depth = child.depth + 1
            if depth > 16:
                raise PolicyError("depth")
            return Pred("not", child=child, atoms=child.atoms, depth=depth)
        raise PolicyError("syntax")

    def parse(self):
        rules = []
        complex_count = 0
        while True:
            if self.lex.peek() is None:
                break
            pred = self._predicate(1)
            act = self.lex.expect("WORD")
            if act[1] not in ("allow", "drop"):
                raise PolicyError("syntax")
            self.lex.expect(";")
            if pred.kind != "match":
                complex_count += 1
                if complex_count > 8:
                    raise PolicyError("complex rule bound")
                if pred.atoms > 32:
                    raise PolicyError("expression atom bound")
            rules.append((pred, act[1]))
        # The AST uses Pred("atom", ...) internally; user-facing AST views
        # are not important, but keeping this one-kind representation makes
        # the evaluator compact.
        return ParsedPolicy(rules, self.atoms, self.path_symbols,
                            self.match_paths, tuple(self.nonmatch_atoms),
                            frozenset(self.referenced))

def parse_policy(text):
    """Parse and bounds-check one policy string.

    Raises PolicyError for grammar or per-string bound failures.  Registry
    membership is deliberately not considered here.
    """
    if type(text) is not str:
        raise PolicyError("type")
    return _Parser(text).parse()

def parse(text, names=None):
    """Compatibility helper: return (parsed_policy, atoms, path_symbols).

    If *names* is supplied, paths containing names outside it raise, as the
    starter syntax module did.  The driver uses :func:`parse_policy` so that
    occurrence totals can be counted before registry checking.
    """
    p = parse_policy(text)
    if names is not None:
        for n in p.referenced_names:
            if n not in names:
                raise PolicyError("unregistered")
    return p, p.atoms, p.path_symbols
